/**
 * Domain types.
 *
 * The ones that describe what travels on the wire come from the OpenAPI spec and are not
 * written by hand: `src/generated/openapi.ts` is generated by `openapi-typescript` from
 * `spec/openapi.yaml`, which is a copy of the spec published at
 * https://docs.veriko.mx/openapi.yaml.
 *
 * This file puts short names on those types and adds the ones the SDK needs and the spec
 * does not describe, such as the shape of a webhook delivery.
 */

import type { components, operations } from './generated/openapi.js';
import type { CallOptions } from './http.js';

type Schemas = components['schemas'];

/** The JSON body of a response, by operation and status. */
type JsonBody<T> = T extends { content: { 'application/json': infer B } } ? B : never;

/** The `data` resource of a body shaped `{ data?: ... }`. */
type DataOf<B> = B extends { data?: infer D } ? NonNullable<D> : never;

/** The `data` of the response of an operation, as the spec types it. */
type ResourceOf<
  Op extends keyof operations,
  Code extends keyof operations[Op]['responses'],
> = DataOf<JsonBody<operations[Op]['responses'][Code]>>;

/** JSON:API resource of a SPEI validation, as the API returns it. */
export type Validation = Schemas['Validation'];

/** Automatic retry policy of a validation. */
export type RetryPolicy = Schemas['RetryPolicy'];

/**
 * Body of `POST /v1/validate`.
 *
 * This one does not come from the generator. The schema in the spec carries an `anyOf`
 * that only expresses "`tracking_key` or `numeric_reference` is required", and
 * `openapi-typescript` turns it into `{...} | unknown`, which TypeScript collapses to
 * `unknown`. The type is written here with the same fields, and `test/spec.test.ts`
 * fails if the spec adds, removes or renames one.
 */
export interface ValidationRequest {
  /**
   * Date of the transfer in ISO 8601 format (`YYYY-MM-DD`). Optional: if it is missing or
   * unusable, the API tries candidate dates against Banxico.
   */
  send_date?: string;
  /** Amount in pesos, greater than zero, with up to two decimals and up to 13 integer digits. */
  amount?: number;
  /** Tracking key, from 1 to 30 characters. */
  tracking_key?: string;
  /** Numeric reference, from 1 to 7 digits. */
  numeric_reference?: string;
  /** Name or SPEI code of the sender bank. */
  sender_bank?: string;
  /** Name or SPEI code of the receiver bank. */
  receiver_bank?: string;
  /** CLABE (18 digits), card (16) or DiMo phone (10) of the beneficiary. Excludes `candidate_accounts`. */
  beneficiary_account?: string;
  /**
   * From 2 accounts up to the maximum the platform allows (3 by default, never more than
   * 10), among which is the receiving one, for when it is not known which it was. Goes
   * instead of `beneficiary_account`.
   */
  candidate_accounts?: string[];
  /** `true` when the beneficiary is the receiving institution itself. */
  recipient_is_bank?: boolean;
  /** Automatic retry policy of the API. */
  retry_policy?: RetryPolicy;
  /** Reference of your own, from 1 to 64 characters, that returns in the validation and in webhooks. */
  client_ref?: string;
}

/**
 * The fields of `ValidationRequest`, for the test that compares them with the spec. The
 * order is the spec's.
 */
export const VALIDATION_REQUEST_FIELDS = [
  'send_date',
  'amount',
  'tracking_key',
  'numeric_reference',
  'sender_bank',
  'receiver_bank',
  'beneficiary_account',
  'candidate_accounts',
  'recipient_is_bank',
  'retry_policy',
  'client_ref',
] as const;

/**
 * Body of `POST /v1/validate-ocr`.
 *
 * It does not come from the generator either, for the same reason as `ValidationRequest`:
 * the `anyOf` that requires `image` or `image_url` becomes `unknown`. The fields are the
 * spec's, and `test/spec.test.ts` fails if they change.
 */
export interface OcrValidationRequest {
  /** The receipt in base64. JPEG, PNG, WebP or a PDF of 1 to 3 pages, up to 12 MB. */
  image?: string;
  /** Public HTTPS URL of the receipt. If `image` also travels, only that one is considered. */
  image_url?: string;
  /** CLABE (18 digits), card (16) or DiMo phone (10). Required for DiMo. Excludes `candidate_accounts`. */
  beneficiary_account?: string;
  /** From 2 accounts up to the platform maximum, among which is the receiving one. Goes instead of `beneficiary_account`. */
  candidate_accounts?: string[];
  /** SPEI code of the sender bank (4 or 5 digits) that replaces the one read from the receipt. */
  sender_bank?: string;
  /** SPEI code of the receiver bank (4 or 5 digits) that replaces the one read from the receipt. */
  receiver_bank?: string;
  /** `true` when the beneficiary is the receiving institution itself. */
  recipient_is_bank?: boolean;
  /** Automatic retry policy of the API. */
  retry_policy?: RetryPolicy;
  /** Reference of your own, from 1 to 64 characters, that returns in the validation and in webhooks. */
  client_ref?: string;
  /** `false` deletes the receipt file as soon as the validation no longer needs it. */
  retain_image?: boolean;
}

/** The fields of `OcrValidationRequest`, for the test that compares them with the spec. */
export const OCR_VALIDATION_REQUEST_FIELDS = [
  'image',
  'image_url',
  'beneficiary_account',
  'candidate_accounts',
  'sender_bank',
  'receiver_bank',
  'recipient_is_bank',
  'retry_policy',
  'client_ref',
  'retain_image',
] as const;

/** Summary state of the retry cycle, as it travels in the response. */
export type RetryState = Schemas['RetryStateCompact'];

/** One entry of the `errors` array. */
export type ErrorObject = Schemas['ErrorObject'];

/** The attributes of a validation. */
export type ValidationAttributes = Validation['attributes'];

/** Lifecycle state of a validation. */
export type ValidationStatus = NonNullable<ValidationAttributes['status']>;

/** Verdicts that admit automatic retry. */
export const RETRYABLE_OUTCOMES = ['not_found', 'cep_unavailable', 'error'] as const;

/** States in which a validation no longer changes by itself (`x-terminal-values` of the spec). */
export const TERMINAL_STATUSES = [
  'valid',
  'not_found',
  'cep_unavailable',
  'invalid',
  'returned',
  'failed',
  'error',
] as const;

/** `true` when the state will not change without an outside action. */
export function isTerminal(status: string | undefined): boolean {
  return TERMINAL_STATUSES.includes(status as (typeof TERMINAL_STATUSES)[number]);
}

/**
 * `true` when the verdict will no longer change, not even through retries.
 *
 * `isTerminal()` looks at the state only. A `not_found` is terminal for the query that
 * produced it, but if the validation has a retry cycle running the API asks Banxico again,
 * and the verdict can change. Only outcomes that admit retry (`RETRYABLE_OUTCOMES`) keep
 * the cycle alive: a `valid` or a `returned` is final even if a policy is configured.
 * This is the condition `waitFor()` waits for.
 */
export function isSettled(validation: Validation): boolean {
  const status = validation.attributes.status;
  if (!isTerminal(status)) return false;
  if (!RETRYABLE_OUTCOMES.includes(status as (typeof RETRYABLE_OUTCOMES)[number])) return true;
  const state = validation.attributes.retry_state;
  const cycleAlive =
    state?.enabled === true &&
    (state.terminal_state === undefined ||
      state.terminal_state === null ||
      state.terminal_state === 'pending');
  return !cycleAlive;
}

/**
 * `true` when there is a receipt to download.
 *
 * It is derived from `links.cep_xml`, which is what the server publishes. A `returned`
 * born from `cep_unavailable` does not carry it.
 */
export function hasCep(validation: Validation): boolean {
  return Boolean(validation.links?.cep_xml);
}

/** A validation read with `get()`, with the `ETag` of the response. */
export type ValidationWithEtag = Validation & {
  /** Send it as `ifNoneMatch` in the next read. */
  etag?: string;
};

/** Formats in which the API delivers the receipt. */
export const CEP_FORMATS = ['xml', 'pdf'] as const;
export type CepFormat = (typeof CEP_FORMATS)[number];

/** Formats of exports. */
export const EXPORT_FORMATS = ['csv', 'xlsx'] as const;
export type ExportFormat = (typeof EXPORT_FORMATS)[number];

/** A file the API returns: the CEP, an image or an export. */
export interface DownloadedFile {
  /** The content of the file. */
  content: Uint8Array;
  contentType: string;
  /** The name that `Content-Disposition` proposes. */
  filename: string;
  /**
   * The response headers, with lowercase names. A finance ZIP carries `x-finance-items`, a
   * statement `x-finance-folio`.
   */
  headers: Record<string, string>;
}

/**
 * A file the API returns, handed over as a stream the SDK has not read. It is what the
 * `*Stream()` variants of the downloads resolve to.
 *
 * The body is a web `ReadableStream`: pipe it to a file or to a response, or read it with
 * `getReader()`. Read it to the end or cancel it, so the connection is released. The time
 * limit of the call (`timeoutMs`) covers the wait for the headers, not the transfer; a
 * `signal` passed in the call options still cancels the transfer.
 */
export interface DownloadedStream {
  /** The body, unread. It is not buffered and not retried. */
  stream: ReadableStream<Uint8Array>;
  contentType: string;
  /** The name that `Content-Disposition` proposes. */
  filename: string;
  /** `Content-Length`, when the response carries it. */
  contentLength: number | undefined;
  /** The response headers, with lowercase names. */
  headers: Record<string, string>;
}

/** The CEP of a validation, as a stream. */
export interface CepStream extends DownloadedStream {
  validationId: string;
  format: CepFormat;
}

/** The CEP downloaded from Banxico: the file, not a link. */
export interface CepDocument extends DownloadedFile {
  validationId: string;
  format: CepFormat;
}

/** Event types that outgoing webhooks emit. */
export const WEBHOOK_EVENTS = [
  'validation.completed',
  'validation.failed',
  'validation.error',
  'validation.retry.scheduled',
  'validation.retry.resolved',
  'validation.retry.exhausted',
  'validation.returned',
  'billing.payment_succeeded',
  'billing.payment_failed',
  'billing.trial_will_end',
  'billing.subscription_canceled',
  'billing.invoice_upcoming',
] as const;
export type WebhookEventName = (typeof WEBHOOK_EVENTS)[number];

/**
 * What Banxico confirmed about the payment, included in the webhook delivery only when
 * the API already has it (`banxico_status` is `valid`, or `returned` with a downloaded
 * CEP). It serves to compare the amount, and the account if it applies, against the order
 * before treating a transfer as paid: a receipt image can show an amount different from
 * the one Banxico confirmed.
 *
 * It does not come from the generator: it belongs to the webhook delivery. The
 * `Validation` resource the API returns exposes the same data unmasked, with more fields,
 * in `attributes.banxico_result`.
 */
export interface BanxicoConfirmed {
  /** Amount of the operation that Banxico confirmed, in pesos. */
  amount?: number;
  /** Date of the operation as the CEP reports it (`DD-MM-YYYY`). */
  operationDate?: string;
  /** Time of the operation as the CEP reports it (`HH:MM:SS`). */
  processingTime?: string;
  /** Tracking key of the SPEI operation. */
  trackingKey?: string;
  /** Sender bank of the operation. */
  senderBank?: string;
  /** Receiver bank of the operation. */
  receiverBank?: string;
  /** Account of the beneficiary, masked to the last 4 digits. */
  beneficiaryAccount?: string;
}

/**
 * The official state of the payment, as Banxico gave it the last time it was asked. It
 * travels in `attributes.payment_status` of the `validation.returned` event and in
 * `attributes.banxico_result._payment_status` of the validation.
 *
 * With `devuelto` or `en_proceso_devolucion` the validation becomes `returned`.
 * `checked_at` is the instant of the query, in ISO 8601 UTC. The codes are Banxico's
 * and stay in Spanish.
 */
export interface PaymentStatus {
  code:
    | 'liquidado'
    | 'en_proceso'
    | 'cancelado'
    | 'rechazado'
    | 'en_proceso_devolucion'
    | 'devuelto'
    | 'desconocido'
    | (string & {});
  label?: string;
  settled?: boolean;
  reversed?: boolean;
  checked_at?: string;
}

/** The resource of a validation as it arrives in a webhook delivery. */
export type WebhookValidation = Validation & {
  attributes: Validation['attributes'] & {
    banxico_confirmed?: BanxicoConfirmed;
    /** Only in `validation.returned`: the payment state that revealed the return. */
    payment_status?: PaymentStatus;
  };
};

/** The events of a validation: the verdicts and the steps of the automatic retries. */
export const VALIDATION_WEBHOOK_EVENTS = [
  'validation.completed',
  'validation.failed',
  'validation.error',
  'validation.retry.scheduled',
  'validation.retry.resolved',
  'validation.retry.exhausted',
  'validation.returned',
] as const;
export type ValidationWebhookEventName = (typeof VALIDATION_WEBHOOK_EVENTS)[number];

/** The events about the subscription of the account. */
export const BILLING_WEBHOOK_EVENTS = [
  'billing.payment_succeeded',
  'billing.payment_failed',
  'billing.trial_will_end',
  'billing.subscription_canceled',
  'billing.invoice_upcoming',
] as const;
export type BillingWebhookEventName = (typeof BILLING_WEBHOOK_EVENTS)[number];

/** Fields every delivery body carries, plus what the SDK reads from the headers. */
export interface WebhookEnvelope {
  /** The time of the event, in ISO 8601 UTC. It is not the time of the delivery attempt. */
  timestamp?: string;
  /** The `data` of the body as it arrived, for any event type. */
  rawData?: unknown;
  meta?: Record<string, unknown>;
  /** `X-Veriko-Delivery-Id`, when `parseWebhook()` received the headers. Stable across retries. */
  deliveryId?: string;
  /** The `t` of the timestamped signature, in Unix seconds, when `parseWebhook()` got the headers. */
  attemptTimestamp?: number;
}

/**
 * `validation.completed`, `.failed`, `.error` and the three `.retry.*`: `data` is the
 * resource of the validation, with `banxico_confirmed` once Banxico confirmed the CEP.
 */
export interface ValidationWebhookEvent extends WebhookEnvelope {
  event: Exclude<ValidationWebhookEventName, 'validation.returned'>;
  data: WebhookValidation;
}

/**
 * `validation.returned`: the same body as `validation.completed`, plus
 * `attributes.payment_status`, the payment status that gave the return away.
 */
export interface ValidationReturnedWebhookEvent extends WebhookEnvelope {
  event: 'validation.returned';
  data: WebhookValidation & {
    attributes: WebhookValidation['attributes'] & { payment_status: PaymentStatus };
  };
}

/**
 * `billing.*`: the API does not publish the shape of its `data`, so it is not typed. It is
 * in `rawData`.
 */
export interface BillingWebhookEvent extends WebhookEnvelope {
  event: BillingWebhookEventName;
  data?: undefined;
}

/** The synthetic delivery of `webhooks.test()`. Its `data` is in `rawData`. */
export interface TestWebhookEvent extends WebhookEnvelope {
  event: 'test';
  data?: undefined;
}

/**
 * An event this version of the SDK does not know. `data` is in `rawData`. A new event of
 * the API arrives as this type, so an existing integration does not break.
 */
export interface UnknownWebhookEvent extends WebhookEnvelope {
  event: string;
  data?: undefined;
}

/**
 * The body of a webhook delivery, discriminated by `event`.
 *
 * ```ts
 * const event = parseWebhook(body, request.headers, secret);
 * if (!isKnownWebhookEvent(event)) return; // an event of a newer API
 * switch (event.event) {
 *   case 'validation.returned':
 *     event.data.attributes.payment_status.code; // typed
 *     break;
 *   case 'validation.completed':
 *     event.data.attributes.banxico_confirmed;
 *     break;
 * }
 * ```
 *
 * `parseWebhook()` returns `WebhookEvent | UnknownWebhookEvent`. The API does not publish
 * the delivery bodies in its spec; these types follow the webhooks documentation.
 */
export type WebhookEvent =
  ValidationWebhookEvent | ValidationReturnedWebhookEvent | BillingWebhookEvent | TestWebhookEvent;

/**
 * The account of a validation by fields: a single one, in `beneficiaryAccount`, or several
 * in `candidateAccounts` when it is not known which it was. Send one of the two, not both.
 */
export type TransferAccountParams =
  | {
      /** CLABE, card or DiMo phone of the beneficiary. */
      beneficiaryAccount: string;
      candidateAccounts?: never;
    }
  | {
      beneficiaryAccount?: never;
      /**
       * From 2 accounts up to the maximum the platform allows (3 by default, never more
       * than 10), among which is the receiving one, in one validation and with one unit of
       * quota. `attributes.candidate_match` says which one matched.
       */
      candidateAccounts: readonly string[];
    };

/**
 * The amount of a validation by fields, in `amount`. It is required.
 */
export type TransferAmountParams = {
  /**
   * Amount in pesos, greater than zero, with up to two decimals and up to 13 integer
   * digits. A decimal string such as `'15000.50'` is sent as the number it spells.
   */
  amount: number | string;
};

/** The arguments of `validateTransfer()`, without the account or the amount. */
interface ValidateTransferBase {
  /**
   * Send date of the transfer, `YYYY-MM-DD`. Optional: if it is missing or unusable, the
   * API tries candidate dates against Banxico, and rejects with `422`
   * (`send_date_required`) only when it has nothing to guess it from.
   */
  sendDate?: string;
  /** Tracking key, from 1 to 30 characters. */
  trackingKey?: string;
  /** Numeric reference, from 1 to 7 digits. */
  numericReference?: string;
  /** Name or SPEI code of the sender bank. */
  senderBank?: string;
  /** Name or SPEI code of the receiver bank. */
  receiverBank?: string;
  /**
   * `true` when the beneficiary of the transfer is the receiving institution itself
   * ("Pago a Banco" in the CEP). `false` by default. `1` and `0` are also accepted and
   * converted.
   */
  recipientIsBank?: boolean | 0 | 1;
  /** Automatic retry policy of the API. */
  retryPolicy?: RetryPolicy;
  /** Reference of your own, from 1 to 64 characters, that returns in the validation and in webhooks. */
  clientRef?: string;
  /**
   * Identifier of the business attempt: the order, batch or transaction number. With it,
   * repeating the request does not duplicate the validation for 24 hours. When it is
   * missing, the SDK generates one per call.
   */
  idempotencyKey?: string;
}

/** The arguments of `validateTransfer()`, `validations.validate()` and `validations.enqueue()`. */
export type ValidateTransferParams = ValidateTransferBase &
  TransferAmountParams &
  TransferAccountParams;

/** The arguments of a validation by fields with canonical names, already resolved. Internal. */
export interface CanonicalTransferParams {
  sendDate?: string;
  amount?: number | string;
  trackingKey?: string;
  numericReference?: string;
  senderBank?: string;
  receiverBank?: string;
  beneficiaryAccount?: string;
  candidateAccounts?: readonly string[];
  recipientIsBank?: boolean | 0 | 1;
  retryPolicy?: RetryPolicy;
  clientRef?: string;
  idempotencyKey?: string;
}

// ── Families `validations`, `webhooks` and `catalog` ────────────────────────

/**
 * A validation in a list.
 *
 * It is narrower than `Validation`: a list carries neither the submitted data nor the
 * Banxico result, nor the links to the receipt. `get()` returns the full one.
 */
export type ValidationSummary = Schemas['PublicValidationListItem'];

/** The totals of the validations of the account. */
export type ValidationStats = ResourceOf<'validationStats', 200>;

/** One attempt of the automatic retry cycle of a validation. */
export type RetryAttempt = Schemas['RetryAttempt'];

/** What the policy change and the cancellation return: the state of the cycle. */
export type RetryStateResource = ResourceOf<'updateValidationRetryPolicy', 200>;

/** The acknowledgment of sending the receipt to Telegram. */
export type TelegramDispatch = ResourceOf<'sendCepToTelegram', 202>;

/** The result of the recheck that accompanies the response of `recheck()`, as the spec types it. */
export type ValidationRecheckMeta = Schemas['ValidationRecheckMeta'];

/**
 * The result of querying the payment state of a validation again.
 *
 * @see https://docs.veriko.mx/en/concepts/cep-concept
 */
export interface RecheckResult {
  /** The validation with the current state. */
  validation: Validation;
  /**
   * The instant of the Banxico query, in ISO 8601 UTC. `null` when nothing was queried
   * because the validation was already `returned`.
   */
  checkedAt: string | null;
  /** `true` when this query moved the validation from `valid` to `returned`. */
  changed: boolean;
  /** The Banxico verdict before the query: `valid` or `returned`. */
  previousStatus: ValidationRecheckMeta['previous_status'];
}

/**
 * What the permanent deletion of a validation would erase, and the token that confirms it.
 * Nothing has changed yet. `attributes.confirmation_token` is single-use and expires in
 * `attributes.expires_in` seconds.
 *
 * @see https://docs.veriko.mx/en/how-to/purge-a-validation
 */
export type PurgePreparation = ResourceOf<'prepareValidationPurge', 200>;

/**
 * The result of the permanent deletion of a validation, which remains as a tombstone.
 * `attributes.file_removal` is `pending` when some file could not be deleted at that
 * moment and the daily sweep finishes it.
 *
 * @see https://docs.veriko.mx/en/how-to/purge-a-validation
 */
export type PurgeResult = ResourceOf<'executeValidationPurge', 200>;

/** The arguments of `validations.executePurge()`. */
export interface ExecutePurgeParams {
  /** The token that `preparePurge()` returned for this same validation. */
  confirmationToken: string;
}

/** The resource of the `202` response of a queued validation. */
export type ValidationQueuedResource = NonNullable<Schemas['ValidationQueued']['data']>;

/**
 * The acknowledgment of a queued validation.
 *
 * The verdict is collected with `waitFor()`, or arrives by webhook.
 *
 * @see https://docs.veriko.mx/en/concepts/async-validations
 */
export interface QueuedValidation {
  /** The identifier of the validation. */
  id: string;
  status: string;
  /** `ETag` of the response, for the first conditional poll. */
  etag: string | undefined;
  /** `Location` of the response: the path of the validation. */
  location: string | undefined;
  /** Seconds the API asks to wait before the first poll. */
  nextPollAfterSeconds: number | undefined;
  /** `meta.async_reason`: `sync_deadline` when a synchronous call outlasted its 45 seconds. */
  asyncReason: string | undefined;
  /** `attributes.expires_at`: past it, the validation closes as expired (`ttl_expired`). */
  expiresAt: string | undefined;
  /** The resource as the API returned it, with `enqueued_at` and `expires_at`. */
  data: ValidationQueuedResource;
}

/** What a `202` carries when a synchronous validation outlasts its deadline. */
export interface QueuedInfo {
  /** `sync_deadline`: the Banxico query passed 45 seconds and continues in the background. */
  asyncReason: string | undefined;
  /** Seconds the API asks to wait before polling. */
  nextPollAfterSeconds: number | undefined;
  etag: string | undefined;
  location: string | undefined;
  /** `attributes.expires_at`. */
  expiresAt: string | undefined;
}

/**
 * What `validate()` and `validateOcr()` return. `queued` is set when the API answered
 * `202` because the Banxico query outlasted 45 seconds: the resource is then the reduced
 * one of a queued validation, its `status` is `processing`, and the verdict is collected
 * with `waitFor()`. It is `undefined` when the response is the verdict.
 */
export type ValidationResult = Validation & { queued?: QueuedInfo };

/** An endpoint of webhooks. `attributes.secret` comes only when registering and rotating it. */
export type WebhookEndpoint = Schemas['WebhookEndpoint'];

/** One delivery attempt of a webhook, with what the receiver answered. */
export type WebhookDelivery = Schemas['WebhookDelivery'];

/** The result of the test event of an endpoint. */
export type WebhookTestResult = ResourceOf<'sendWebhookTest', 200>;

/** An event an endpoint subscribes to. */
export type WebhookSubscriptionEvent = Schemas['CreateWebhookRequest']['events'][number];

/** State that can be assigned to an endpoint. `auto_disabled` is set by the system. */
export type WebhookStatus = NonNullable<Schemas['UpdateWebhookRequest']['status']>;

/** The arguments of `webhooks.regenerateSecret()`. */
export interface RegenerateSecretParams {
  /**
   * `true` revokes the previous secret at once, with no grace period. Use it if the secret
   * was exposed. Without it, the previous secret keeps signing for 24 hours in
   * `X-Webhook-Signature-Old`, until `attributes.previous_secret_expires_at`.
   */
  immediate?: boolean;
}

/** An institution of the SPEI catalog. */
export type Bank = Schemas['BankResource'];

/** The catalog of banks, with the `ETag` of the response when the API sends it. */
export type BankList = Bank[] & { etag?: string };

/** The issuing bank of a card, resolved by its BIN. */
export type BinLookup = Schemas['BinResource'];

/**
 * The calendar of SPEI non-business days of a year, with the provision it comes from.
 *
 * `attributes.non_business_days` carries only the non-business days from Monday to Friday;
 * Saturdays and Sundays are always non-business.
 */
export type SpeiCalendar = Schemas['SpeiCalendarResource'] & {
  /** The years with a calendar, ascending (`meta.covered_years`). */
  coveredYears: number[];
  /** Send it as `ifNoneMatch` in the next read. */
  etag?: string;
};

/** Current state of the Banxico query service. */
export type BanxicoStatus = Schemas['BanxicoPublicStatusResource'];

/** Time series of the health of the Banxico service. */
export type BanxicoTimeseries = Schemas['BanxicoPublicTimeseriesResource'];

/** Consolidated profile of the authenticated account. */
export type UserProfile = ResourceOf<'myProfile', 200>;

/** Default retry policy of the account. */
export type UserRetryPolicy = ResourceOf<'getMyRetryPolicy', 200>;

/** Summary of the account dashboard. */
export type DashboardSummary = ResourceOf<'getDashboardSummary', 200>;

/** Plans visible to an unauthenticated integration. */
export type PublicPlans = ResourceOf<'listPublicPlans', 200>;

/** Comparison matrix of visible plans. */
export type PublicPlanComparison = ResourceOf<'getPublicPlanComparison', 200>;

