/** The reports `finance.reportStream()` can stream. */
export type FinanceReport = 'monthly' | 'counterparties' | 'by-bank' | 'accounting';

/** The arguments of `finance.reportStream()`: a file format, never `preview`. */
export interface FinanceReportStreamParams extends Omit<FinanceAccountingParams, 'format'> {
  format?: Exclude<FinancePreviewFormat, 'preview'>;
  // `decimal` is read by the `accounting` report only.
}

export interface FinanceCepsParams {
  from: string;
  to: string;
  userId?: string;
}

/** The arguments of `finance.createCepExport()`. */
export interface FinanceCepExportParams extends FinanceCepsParams {
  /** Repeating the same request with this key does not queue a second archive. */
  idempotencyKey?: string;
}

/** A background CEP export: `id`, `attributes.status` and `links`. */
export type FinanceCepExport = ResourceOf<'getFinanceCepExport', 200>;

/** States of a CEP export in which it no longer changes (`x-terminal-values` of the spec). */
export const CEP_EXPORT_TERMINAL_STATUSES = ['ready', 'failed', 'expired'] as const;

/** `true` when the export reached `ready`, `failed` or `expired`. */
export function isCepExportTerminal(status: string | undefined): boolean {
  return CEP_EXPORT_TERMINAL_STATUSES.includes(
    status as (typeof CEP_EXPORT_TERMINAL_STATUSES)[number],
  );
}

type ListValidationsQuery = NonNullable<operations['listValidations']['parameters']['query']>;
type TimeseriesQuery = NonNullable<operations['banxicoPublicTimeseries']['parameters']['query']>;
type DeliveriesQuery = NonNullable<operations['listAllDeliveries']['parameters']['query']>;
type ImportPreviewQuery = NonNullable<
  operations['getBeneficiaryImportPreview']['parameters']['query']
>;

/** Mode of a validation. */
export type ValidationType = NonNullable<ListValidationsQuery['type']>;

/** State of the retry cycle, for filtering. */
export type RetryStateFilter = NonNullable<ListValidationsQuery['retry_state']>;

/** Metric of the Banxico time series. */
export type BanxicoMetric = NonNullable<TimeseriesQuery['metric']>;

/** Window of the Banxico time series. */
export type BanxicoWindow = NonNullable<TimeseriesQuery['window']>;

/** State of a delivery, for filtering. */
export type DeliveryStatus = NonNullable<DeliveriesQuery['status']>[number];

/** Event type of a delivery, for filtering. */
export type DeliveryEventType = NonNullable<DeliveriesQuery['event_type']>[number];

/**
 * The account of a validation by image: `beneficiaryAccount`, or several in
 * `candidateAccounts` when it is not known which it was. Send one of the two, not both.
 */
export type OcrAccountParams =
  | {
      /** CLABE, card or DiMo phone. Required for DiMo. */
      beneficiaryAccount?: string;
      candidateAccounts?: never;
    }
  | {
      beneficiaryAccount?: never;
      /** From 2 accounts up to the platform maximum, among which is the receiving one, with one unit of quota. */
      candidateAccounts: readonly string[];
    };

/** The arguments of `validations.validateOcr()` and `validations.enqueueOcr()`, without the account. */
interface ValidateOcrBase {
  /**
   * The receipt: its bytes (`Buffer` or `Uint8Array`) or the path of a file. The SDK
   * encodes it in base64. JPEG, PNG, WebP or a PDF of 1 to 3 pages, up to 12 MB.
   */
  image?: Uint8Array | string;
  /** Public HTTPS URL of an already published image. If `image` is also sent, only that one counts. */
  imageUrl?: string;
  /** Automatic retry policy of the API. */
  retryPolicy?: RetryPolicy;
  /** Reference of your own, from 1 to 64 characters, that returns in the validation and in webhooks. */
  clientRef?: string;
  /**
   * `true` by default: the platform keeps the receipt file and `image()` serves it. With
   * `false` it deletes it as soon as the validation reaches a terminal state in which it
   * no longer needs it, and `attributes.image_retained` is `false`.
   */
  retainImage?: boolean;
  /**
   * SPEI code of the sender bank, 4 or 5 digits (`'40012'`), that replaces the one read
   * from the receipt before querying Banxico. A value in another format, such as a name,
   * is ignored and the one read is kept.
   */
  senderBank?: string;
  /** SPEI code of the receiver bank, with the same rule as `senderBank`. */
  receiverBank?: string;
  /**
   * `true` when the beneficiary is the receiving institution itself. `1` and `0` are also
   * accepted and converted.
   */
  recipientIsBank?: boolean | 0 | 1;
  /** Identifier of the business attempt. With it, repeating the request does not duplicate the validation. */
  idempotencyKey?: string;
}

/** The arguments of `validations.validateOcr()` and `validations.enqueueOcr()`. */
export type ValidateOcrParams = ValidateOcrBase & OcrAccountParams;

/** The arguments of a validation by image with canonical names, already resolved. Internal. */
export interface CanonicalOcrParams {
  image?: Uint8Array | string;
  imageUrl?: string;
  beneficiaryAccount?: string;
  candidateAccounts?: readonly string[];
  senderBank?: string;
  receiverBank?: string;
  recipientIsBank?: boolean | 0 | 1;
  retryPolicy?: RetryPolicy;
  clientRef?: string;
  retainImage?: boolean;
  idempotencyKey?: string;
}

/** The options of `validations.get()`. */
export interface GetValidationOptions extends CallOptions {
  /**
   * The `ETag` of an earlier read. When nothing changed, the API answers `304` and the SDK
   * throws it as `NotModifiedError`, whose `etag` is the current one.
   */
  ifNoneMatch?: string;
}

/** The options of `validations.waitFor()`, `finance.waitForCepExport()` and `beneficiaries.importWait()`. */
export interface WaitForOptions extends Omit<CallOptions, 'timeoutMs'> {
  /**
   * How long to wait for the result, in milliseconds. By default, up to the `expires_at` of
   * the validation, when the API reported one, and five minutes otherwise.
   */
  timeoutMs?: number;
  /**
   * Floor of the pause between polls, in milliseconds. The pause is never shorter than what
   * the server asks in `Retry-After` or `meta.next_poll_after_seconds`. Without a server
   * hint, it is this value, 2 seconds by default.
   */
  pollIntervalMs?: number;
  /** Time limit of each request of the polling, in milliseconds. */
  requestTimeoutMs?: number;
  /** Replaceable in tests so they do not sleep for real. */
  sleep?: (ms: number) => Promise<void>;
}

/** The filters shared by the list, the statistics and the export. */
export interface ValidationFilters {
  /** One state, or several: `valid`, `not_found`, `cep_unavailable`, `returned`... */
  status?: ValidationStatus | (string & {}) | readonly (ValidationStatus | (string & {}))[];
  /** `direct` for manual capture, `ocr` for validation with a receipt (image or PDF). */
  type?: ValidationType;
  /** Start date, inclusive, `YYYY-MM-DD`, on the creation of the validation. */
  from?: string;
  /** End date, inclusive, `YYYY-MM-DD`. */
  to?: string;
  /** Text searched in the submitted data and in the data Banxico returned. */
  search?: string;
  /** Only the validations of the test bench (Playground). */
  playground?: true;
  /** `true` only the removed ones, `false` only the active ones; without it, both. */
  withDeleted?: boolean;
  /** Identifier of the import job that generated the validations. */
  batchId?: number;
  /** SPEI code of the sender or receiver bank. */
  bank?: string;
  /**
   * Up to 50 SPEI codes, as a list or comma-separated: the validations whose sender or
   * receiver bank is any of them. With `bank`, both are met.
   */
  banks?: string | readonly string[];
  amountMin?: number;
  amountMax?: number;
  /** Exact match with the `client_ref` sent when validating. */
  clientRef?: string;
  retryState?: RetryStateFilter;
}

/** The arguments of `validations.list()`. */
export interface ListValidationsParams extends ValidationFilters {
  page?: number;
  /** From 1 to 50. A larger value is clamped to 50, not rejected. */
  perPage?: number;
}

/** The arguments of `validations.export()`. */
export interface ExportValidationsParams extends ValidationFilters {
  /** `csv` by default. */
  format?: ExportFormat;
  /** Row cap, from 1 to 100,000. */
  limit?: number;
}

/**
 * The options of the operations that accept `Idempotency-Key`. The SDK generates a key per
 * call when it is missing; pass your own to make a later resend safe.
 */
export type IdempotentOptions = CallOptions;

/** The arguments of `webhooks.create()`. */
export interface CreateWebhookParams {
  /** HTTPS, at most 2048 characters, and not resolving to a private address. */
  url: string;
  /** From 1 to 10 events. */
  events: readonly WebhookSubscriptionEvent[];
  /** Free label to tell the endpoint apart. */
  description?: string;
}

/** The arguments of `webhooks.update()`. At least one is required. */
export interface UpdateWebhookParams {
  url?: string;
  events?: readonly WebhookSubscriptionEvent[];
  /** `null` erases the label. */
  description?: string | null;
  /** `active` reactivates an endpoint the system turned off; `disabled` pauses it. */
  status?: WebhookStatus;
}

/** The filters shared by the delivery list and export. */
export interface DeliveryFilters {
  /** One state, or several. */
  status?: DeliveryStatus | readonly DeliveryStatus[];
  /** One event type, or several. */
  eventType?: DeliveryEventType | readonly DeliveryEventType[];
  /**
   * The HTTP code the receiver answered with: exact (`404`), a family (`'5xx'`) or
   * `'none'` for deliveries with no response. One or several.
   */
  responseStatus?: string | number | readonly (string | number)[];
  /** Only the deliveries of this validation. */
  validationId?: string;
  /** Searches the identifier, the endpoint, the event, the validation and the HTTP code. */
  q?: string;
  /** Created since this moment, included: `YYYY-MM-DD` or an ISO 8601 date and time. */
  from?: string;
  /** Created until this moment, included. A date alone reaches the end of that day in UTC. */
  to?: string;
  /** Minimum attempt number, from 1 to 255. With `2`, only the retries. */
  minAttempt?: number;
  /** Only the responses that took at least these milliseconds, from 0 to 600,000. */
  minResponseTimeMs?: number;
}

/** The arguments of `webhooks.deliveries()`. */
export interface DeliveriesParams extends DeliveryFilters {
  page?: number;
  /** From 1 to 100. A larger value is clamped to 100, not rejected. */
  perPage?: number;
}

/** The arguments of `webhooks.exportDeliveries()`. */
export interface ExportDeliveriesParams extends DeliveryFilters {
  /** `csv` by default. */
  format?: ExportFormat;
  /** Row cap, from 1 to 100,000. */
  limit?: number;
}

/** The arguments of `catalog.banxicoTimeseries()`. */
export interface TimeseriesParams {
  /** `probe_latency` by default. */
  metric?: BanxicoMetric;
  /** `24h` by default. */
  window?: BanxicoWindow;
}

/** The options of `catalog.banks()`. */
export interface BanksOptions extends CallOptions {
  /** The `ETag` of an earlier read; with it, an unchanged catalog answers `304` (`NotModifiedError`). */
  ifNoneMatch?: string;
}

/** The options of `catalog.speiCalendar()`. */
export interface SpeiCalendarOptions extends CallOptions {
  /** The `ETag` of an earlier read; with it, an unchanged calendar answers `304` (`NotModifiedError`). */
  ifNoneMatch?: string;
}

/** The options of `validations.cep()`. */
export interface CepOptions extends CallOptions {
  /** `xml` by default. */
  format?: CepFormat;
}

// ── Families `beneficiaries` and `usage` ────────────────────────────────────

/** A saved beneficiary account: CLABE, card or DiMo phone. */
export type Beneficiary = Schemas['Beneficiary'];

/**
 * The result of `beneficiaries.create()`. `reactivated` is `true` when the registration
 * reactivated an archived account with the same number (the API answers `200` with
 * `meta.reactivated`) and `false` for a new one.
 */
export type CreatedBeneficiary = Beneficiary & { reactivated: boolean };

/** The account that `beneficiaries.lookup()` resolves within the own list. */
export type BeneficiaryLookup = Schemas['BeneficiaryLookupResource'];

/**
 * The structure of an account number, which `beneficiaries.validateAccount()` returns:
 * detected type, check digit and resolved bank. It is a local validation, with no Banxico
 * query.
 */
export interface AccountValidation {
  type: 'account_validation';
  attributes: {
    /** The text received, not normalized. */
    input: string;
    length: number;
    /** `true` when the original text had only digits. */
    is_numeric: boolean;
    account_type: 'clabe' | 'card' | 'phone' | 'unknown';
    /** `true` when the text is complete for its type (18, 16 or 10 digits). */
    is_complete: boolean;
    /** CLABE check digit or card Luhn; for a phone, always `false`. */
    checksum_valid: boolean;
    computed_control_digit?: string | null;
    /** The 18-digit CLABE when 17 arrived and the check digit could be computed. */
    auto_completed?: string | null;
    /** The bank resolved by prefix or BIN, or `null` if it was not identified. */
    bank?: { banxico_code?: string | null; name?: string } | null;
    /** The BIN data when it is a card. */
    card?: {
      bin?: string;
      brand?: string | null;
      type?: string | null;
      level?: string | null;
      country_iso?: string | null;
    } | null;
  };
}

/** The arguments of `beneficiaries.validateAccount()`. */
export interface ValidateAccountParams {
  /** Digits of the account, complete or partial: from 1 to 19. */
  account: string;
  /**
   * Forces the interpretation instead of detecting it by length: `clabe` resolves the bank
   * by prefix even if the CLABE is incomplete; `bin` resolves it as a card BIN.
   */
  type?: 'clabe' | 'bin';
}

/** The acknowledgment of a newly opened import, always in state `pending`. */
export type BeneficiaryImportStarted = Schemas['CreateBeneficiaryImportResource'];

/** A bulk import job and its progress. */
export type BeneficiaryImportJob = Schemas['BeneficiaryImportJob'];

/** A row extracted from an import file, with its bucket and its corrections. */
export type BeneficiaryImportRow = Schemas['BeneficiaryImportRow'];

/** The acknowledgment of confirming an import, in state `committing`. */
export type BeneficiaryImportCommitted = Schemas['CommitBeneficiaryImportResource'];

/** The quota of validations of the current plan. */
export type UsageSummary = ResourceOf<'getUsageSummary', 200>;

/** The monthly usage of the latest months. */
export type UsageHistory = ResourceOf<'getUsageHistory', 200>;

/** The usage broken down by operation type. */
export type UsageBreakdown = ResourceOf<'getUsageBreakdown', 200>;

/** The applicable rate limits, by context. */
export type UsageLimits = ResourceOf<'getUsageLimits', 200>;

/** The validations grouped by day and hour. */
export type UsageHeatmap = Schemas['UsageHeatmapResource'];

/** The API usage metrics of the account. */
export type ApiUsage = ResourceOf<'getApiUsage', 200>;

/** Type of a beneficiary account. */
export type BeneficiaryAccountType = Beneficiary['attributes']['account_type'];

/** The bucket of a row of the preview, for filtering (`buckets` of the preview query). */
export type ImportRowBucket = NonNullable<ImportPreviewQuery['buckets']>[number];

/** How the file is read: `template` (canonical headers) or `free` (free format). */
export type ImportParseMode = Schemas['CreateBeneficiaryImportRequest']['parse_mode'];

/** Formats of the import template. */
export const IMPORT_TEMPLATE_FORMATS = ['csv', 'xlsx', 'xls', 'txt', 'json'] as const;
export type ImportTemplateFormat = (typeof IMPORT_TEMPLATE_FORMATS)[number];

/** Final states of a beneficiary import. */
export const IMPORT_TERMINAL_STATUSES = ['completed', 'failed', 'cancelled'] as const;

/** `true` when the job finished, successfully or not. */
export function isImportTerminal(status: string | undefined): boolean {
  return IMPORT_TERMINAL_STATUSES.includes(status as (typeof IMPORT_TERMINAL_STATUSES)[number]);
}

/**
 * `true` when the job no longer advances by itself.
 *
 * It covers `preview_ready`, where progress stops to wait for the review, and the final
 * states. It is what `importWait()` waits for.
 */
export function isImportSettled(job: BeneficiaryImportJob): boolean {
  const status = job.attributes?.status;
  return status === 'preview_ready' || isImportTerminal(status);
}

/** The arguments of `beneficiaries.create()`. */
export interface CreateBeneficiaryParams {
  /** CLABE (18 digits), card (16) or DiMo phone (10). */
  accountNumber: string;
  /** Required for a phone; for CLABE and card it is derived from the number. */
  bankCode?: string;
  label?: string;
}

/** The arguments of `beneficiaries.update()`. At least one is required. */
export interface UpdateBeneficiaryParams {
  label?: string;
  accountNumber?: string;
  /** Applied only on phone-type accounts. */
  bankCode?: string;
}

/** The arguments of `beneficiaries.list()`. */
export interface ListBeneficiariesParams {
  /** `true` only the archived ones, `false` only the active ones; without it, both. */
  withArchived?: boolean;
}

